                "zh": "結締組織；結締組織類型；固有結締組織；疏鬆結締組織：疏鬆、脂肪、網狀；緻密結締組織：規則、不規則、彈性；支持性結締組織；軟骨：透明、纖維、彈性；骨：密質、鬆質；液體結締組織；血液；淋巴。"
