            "zh": "我們身體構建或修復的新陳代謝部分。合成代謝需要最終來自我們食物的能量。當我們吃得超過日常合成代謝所需時，多餘的營養素通常以脂肪的形式存儲在我們的身體中。合成代謝階段"
