                "t": "(A) Endocytosis: Outside of cell; Cell membrane; Endocytotic vesicle; Inside of cell. (B) Exocytosis: Secretory vesicle; Outside of cell; Inside of cell.",
                "zh": "(A) 胞吞：細胞外；細胞膜；胞吞囊泡；細胞內。(B) 胞吐：分泌囊泡；細胞外；細胞內。"
